// Canonical contract. Copies in client/src/contracts and server/contracts
// are generated by scripts/sync-contracts.cjs, never edited separately.
function assertDashboard(data) {
  const object=(v,p)=>{if(!v||typeof v!=='object'||Array.isArray(v))throw new Error(`Invalid dashboard response: ${p}`);};
  const number=(v,p)=>{if(typeof v!=='number'||!Number.isFinite(v))throw new Error(`Invalid dashboard response: ${p}`);};
  const series=(v,p)=>{if(!Array.isArray(v))throw new Error(`Invalid dashboard response: ${p}`);v.forEach((x,i)=>{object(x,p);if(typeof x.day!=='string'||Number.isNaN(Date.parse(x.day)))throw new Error(`Invalid dashboard response: ${p}[${i}].day`);number(x.revenueCents,p+'.revenueCents');});};
  object(data,'root');
  for(const [group, fields] of Object.entries({overview:['totalSalesCents','newSalesCount'],activeSales:['valueCents','changePct'],productRevenue:['valueCents','changePct'],salesPerformance:['conversionRate','paidCount','totalCount']})){
    object(data[group],group);fields.forEach(f=>number(data[group][f],group+'.'+f));
  }
  series(data.activeSales.last7Days,'activeSales.last7Days');series(data.salesTrend,'salesTrend');
  if(!Array.isArray(data.topProducts))throw new Error('Invalid dashboard response: topProducts');
  data.topProducts.forEach(p=>{object(p,'topProducts entry');['id','unitsSold','revenueCents','stock'].forEach(f=>number(p[f],'topProducts.'+f));if(typeof p.name!=='string'||!['In Stock','Out of Stock'].includes(p.status))throw new Error('Invalid dashboard response: topProducts name/status');});
  return data;
}
module.exports={assertDashboard};
